          <circle cx="31.2" cy="20.6" r={rage >= 4 ? 1.05 : 0.8} fill={rage >= 4 ? "#ff2d3a" : "#ea3943"}
            style={{ filter: `drop-shadow(0 0 ${rage >= 4 ? 3 : 2}px #ff4b55)` }} />
