            const winMs = { "1H": 3600e3, "1D": 864e5, "1W": 6048e5, "1M": 2592e6, "ALL": Infinity }[range];
            const since = Date.now() - winMs;
            const inRange = (activity || []).filter((a) => range === "ALL" || a.t >= since);
