    v.id = 424242; v.price = 0.0125; v.hue = 262; v.momentum = 74; v.isNew = false; v.demoOnly = true;
    v.candles = seedCandles(0.0125, 74); v.traders = 4820; v.tvl = 1950000;
    v.greenUsd = 240000; v.redUsd = 150000;
