        setPendingOrders((P) => [...P, { id: Date.now() + Math.random(), tokenId: t.id, side: "sell", level: lvl, dir, amt: o.amt, pay: o.pay, tax: o.tax, stopLoss: null, tpMult: null, legs: [], ts: Date.now() }]);
