    const sellPnlPct = o.side === "sell" ? ((t.price - posEntry) / posEntry) * 100 : 0;
    const sellPnlMoney = o.side === "sell" ? (payUsd(o.amt, o.pay || pay) * sellPnlPct) / 100 : 0;
